func (p *DockerComposeProvider) Configure(ctx context.Context, req provider.ConfigureRequest, resp *provider.ConfigureResponse) {
	var data DockerComposeProviderModel

	resp.Diagnostics.Append(req.Config.Get(ctx, &data)...)

	if resp.Diagnostics.HasError() {
		return
	}

	port := int64(22)
	if !data.Port.IsNull() {
		port = data.Port.ValueInt64()
	}

	client, err := ssh.NewClient(
		data.Host.ValueString(),
		int(port),
		data.User.ValueString(),
		data.PrivateKey.ValueString(),
	)
	if err != nil {
		resp.Diagnostics.AddError(
			"Unable to Create SSH Client",
