package ssh

import (
	"bytes"
	"fmt"
	"strings"
	"time"

	"golang.org/x/crypto/ssh"
)

// Client represents an SSH client for executing remote commands
type Client struct {
	Host       string
	Port       int
	User       string
	config     *ssh.ClientConfig
	connection *ssh.Client
}

// NewClient creates a new SSH client with the given configuration
func NewClient(host string, port int, user string, privateKey string) (*Client, error) {
	signer, err := ssh.ParsePrivateKey([]byte(privateKey))
	if err != nil {
		return nil, fmt.Errorf("failed to parse private key: %w", err)
	}

	config := &ssh.ClientConfig{
		User: user,
		Auth: []ssh.AuthMethod{
			ssh.PublicKeys(signer),
		},
		HostKeyCallback: ssh.InsecureIgnoreHostKey(), // TODO: Consider implementing proper host key verification
		Timeout:         10 * time.Second,
	}

	return &Client{
		Host:   host,
		Port:   port,
		User:   user,
		config: config,
	}, nil
}

// Connect establishes the SSH connection
func (c *Client) Connect() error {
	addr := fmt.Sprintf("%s:%d", c.Host, c.Port)
	client, err := ssh.Dial("tcp", addr, c.config)
	if err != nil {
		return fmt.Errorf("failed to connect to %s: %w", addr, err)
	}
	c.connection = client
	return nil
}

// Close closes the SSH connection
func (c *Client) Close() error {
	if c.connection != nil {
		return c.connection.Close()
	}
	return nil
}

// Execute runs a command on the remote host and returns the output
func (c *Client) Execute(command string) (string, error) {
	if c.connection == nil {
		if err := c.Connect(); err != nil {
			return "", err
		}
	}

	session, err := c.connection.NewSession()
	if err != nil {
		return "", fmt.Errorf("failed to create session: %w", err)
	}
	defer session.Close()

	var stdout, stderr bytes.Buffer
	session.Stdout = &stdout
	session.Stderr = &stderr

	if err := session.Run(command); err != nil {
		return "", fmt.Errorf("command failed: %w, stderr: %s", err, stderr.String())
	}

	return strings.TrimSpace(stdout.String()), nil
}

// WriteFile writes content to a file on the remote host
func (c *Client) WriteFile(path string, content string) error {
	if c.connection == nil {
		if err := c.Connect(); err != nil {
			return err
		}
	}

	// Use a here-document to write the content
	// First, escape any single quotes in the content
	escapedContent := strings.ReplaceAll(content, "'", "'\"'\"'")

	command := fmt.Sprintf("mkdir -p $(dirname '%s') && cat > '%s' << 'EOFCOMPOSEFILE'\n%s\nEOFCOMPOSEFILE", path, path, escapedContent)

	_, err := c.Execute(command)
	if err != nil {
		return fmt.Errorf("failed to write file %s: %w", path, err)
	}

	return nil
}

// ReadFile reads content from a file on the remote host
func (c *Client) ReadFile(path string) (string, error) {
	return c.Execute(fmt.Sprintf("cat '%s'", path))
}

// FileExists checks if a file exists on the remote host
func (c *Client) FileExists(path string) (bool, error) {
	_, err := c.Execute(fmt.Sprintf("test -f '%s'", path))
	if err != nil {
		if strings.Contains(err.Error(), "exit status 1") {
			return false, nil
		}
		return false, err
	}
	return true, nil
}

// DeleteFile deletes a file on the remote host
func (c *Client) DeleteFile(path string) error {
	_, err := c.Execute(fmt.Sprintf("rm -f '%s'", path))
	return err
}
