}

func (r *ComposeResource) Metadata(ctx context.Context, req resource.MetadataRequest, resp *resource.MetadataResponse) {
	resp.TypeName = req.ProviderTypeName + "_deployment"
}

func (r *ComposeResource) Schema(ctx context.Context, req resource.SchemaRequest, resp *resource.SchemaResponse) {
	resp.Schema = schema.Schema{
		MarkdownDescription: "Manages a Docker Compose deployment on a remote host",

		Attributes: map[string]schema.Attribute{
			"id": schema.StringAttribute{
				Computed:            true,
				MarkdownDescription: "Unique identifier for the deployment",
				PlanModifiers: []planmodifier.String{
					stringplanmodifier.UseStateForUnknown(),
				},
			},
			"project_name": schema.StringAttribute{
				MarkdownDescription: "The name of the Docker Compose project",
				Required:            true,
			},
			"compose_file": schema.StringAttribute{
				MarkdownDescription: "The content of the Docker Compose file",
				Required:            true,
			},
			"working_dir": schema.StringAttribute{
				MarkdownDescription: "The working directory for the compose project on the remote host",
				Optional:            true,
				Computed:            true,
				PlanModifiers: []planmodifier.String{
					stringplanmodifier.UseStateForUnknown(),
				},
			},
			"environment": schema.MapAttribute{
				MarkdownDescription: "Environment variables to pass to Docker Compose",
				Optional:            true,
				ElementType:         types.StringType,
			},
			"containers": schema.ListNestedAttribute{
				MarkdownDescription: "List of containers in the deployment",
				Computed:            true,
				NestedObject: schema.NestedAttributeObject{
					Attributes: map[string]schema.Attribute{
						"name": schema.StringAttribute{
							Computed: true,
						},
						"service": schema.StringAttribute{
							Computed: true,
						},
						"state": schema.StringAttribute{
							Computed: true,
						},
						"health": schema.StringAttribute{
							Computed: true,
						},
					},
				},
			},
			"force_recreate": schema.BoolAttribute{
				MarkdownDescription: "Force recreation of containers on every apply",
				Optional:            true,
			},
		},
	}
}

func (r *ComposeResource) Configure(ctx context.Context, req resource.ConfigureRequest, resp *resource.ConfigureResponse) {
	// Prevent panic if the provider has not been configured.
	if req.ProviderData == nil {
		return
	}

	client, ok := req.ProviderData.(*ssh.Client)

	if !ok {
		resp.Diagnostics.AddError(
			"Unexpected Resource Configure Type",
			fmt.Sprintf("Expected *ssh.Client, got: %T. Please report this issue to the provider developers.", req.ProviderData),
		)

		return
	}

	r.client = client
}

func (r *ComposeResource) Create(ctx context.Context, req resource.CreateRequest, resp *resource.CreateResponse) {
	var data ComposeResourceModel

	// Read Terraform plan data into the model
	resp.Diagnostics.Append(req.Plan.Get(ctx, &data)...)

	if resp.Diagnostics.HasError() {
		return
	}

	// Set default working directory if not provided
	workingDir := data.WorkingDir.ValueString()
	if workingDir == "" {
		workingDir = fmt.Sprintf("/opt/compose/%s", data.ProjectName.ValueString())
		data.WorkingDir = types.StringValue(workingDir)
	}

	// Convert environment map
	env := make(map[string]string)
	if !data.Environment.IsNull() {
		resp.Diagnostics.Append(data.Environment.ElementsAs(ctx, &env, false)...)
		if resp.Diagnostics.HasError() {
			return
		}
	}

	// Create compose manager
	manager := compose.NewManager(r.client, data.ProjectName.ValueString(), workingDir)

	// Deploy the compose stack
	if err := manager.Deploy(data.ComposeFile.ValueString(), env); err != nil {
		resp.Diagnostics.AddError("Failed to deploy Docker Compose stack", err.Error())
		return
	}

	// Set ID
	data.ID = types.StringValue(data.ProjectName.ValueString())

	// Get container status
	containers, err := manager.GetContainers()
	if err != nil {
		resp.Diagnostics.AddWarning("Failed to get container status", err.Error())
	} else {
		containerList, diags := compose.ContainersToTerraformList(ctx, containers)
		resp.Diagnostics.Append(diags...)
		data.Containers = containerList
	}

	// Save data into Terraform state
	resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (r *ComposeResource) Read(ctx context.Context, req resource.ReadRequest, resp *resource.ReadResponse) {
	var data ComposeResourceModel

	// Read Terraform prior state data into the model
	resp.Diagnostics.Append(req.State.Get(ctx, &data)...)

	if resp.Diagnostics.HasError() {
		return
	}

	// Create compose manager
	manager := compose.NewManager(r.client, data.ProjectName.ValueString(), data.WorkingDir.ValueString())

	// Check if the deployment exists
	exists, err := manager.Exists()
	if err != nil {
		resp.Diagnostics.AddError("Failed to check deployment existence", err.Error())
		return
	}

	if !exists {
		resp.State.RemoveResource(ctx)
		return
	}

	// Get container status
	containers, err := manager.GetContainers()
	if err != nil {
		resp.Diagnostics.AddWarning("Failed to get container status", err.Error())
	} else {
		containerList, diags := compose.ContainersToTerraformList(ctx, containers)
		resp.Diagnostics.Append(diags...)
		data.Containers = containerList
	}

	// Save updated data into Terraform state
	resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (r *ComposeResource) Update(ctx context.Context, req resource.UpdateRequest, resp *resource.UpdateResponse) {
	var data ComposeResourceModel

	// Read Terraform plan data into the model
	resp.Diagnostics.Append(req.Plan.Get(ctx, &data)...)

	if resp.Diagnostics.HasError() {
		return
	}

	// Convert environment map
	env := make(map[string]string)
	if !data.Environment.IsNull() {
		resp.Diagnostics.Append(data.Environment.ElementsAs(ctx, &env, false)...)
		if resp.Diagnostics.HasError() {
			return
		}
	}

	// Create compose manager
	manager := compose.NewManager(r.client, data.ProjectName.ValueString(), data.WorkingDir.ValueString())

	// Check if force recreate is enabled
	forceRecreate := false
	if !data.ForceRecreate.IsNull() && data.ForceRecreate.ValueBool() {
		forceRecreate = true
	}

	// Update the compose stack
	if err := manager.Update(data.ComposeFile.ValueString(), env, forceRecreate); err != nil {
		resp.Diagnostics.AddError("Failed to update Docker Compose stack", err.Error())
		return
	}

	// Get container status
	containers, err := manager.GetContainers()
	if err != nil {
		resp.Diagnostics.AddWarning("Failed to get container status", err.Error())
	} else {
